//! Span and hashing load: items.rs (generated by ../../gen.py) holds thousands of small items in
//! one file. ../edits.json describes an edit that shifts every span in it by one line.

mod items;

fn main() {
    let fold = items::FNS.iter().fold(1u32, |acc, f| f(acc));
    assert_eq!(items::FNS.len(), 6_000);
    assert_eq!(fold, items::FOLD);
    // Holds before and after the shift-top edit: both lines move together.
    assert_eq!(items::here() - items::TOP, items::HERE_MINUS_TOP);
    println!("big-file ok: fold {fold:#010x}, here() at line {}", items::here());
}
